<?php
namespace Tests\Feature;
use App\Models\{Company,User,FinancialExpense as Expense,ExpensePayment as Payment,ExpenseEvent as Event,Customer,FinancialQuote,FinancialInstallment,FinancialPayment};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\{Str,Carbon};
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class ExpenseTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $owner;
 protected function setUp():void{parent::setUp();$this->travelTo(Carbon::parse('2026-10-05 15:00:00','UTC'));$this->company=Company::create(['name'=>'Clínica teste','slug'=>'expenses']);$this->owner=$this->user('owner');$this->actingAs($this->owner);}
 private function user(string $role,?Company $c=null):User{return User::create(['company_id'=>($c??$this->company)->id,'name'=>'Usuário '.$role,'email'=>Str::uuid().'@example.test','password'=>'OnlyTest-2026','role'=>$role,'active'=>true]);}
 private function form():array{return ['request_id'=>(string)Str::uuid(),'description'=>'Compra de materiais','supplier'=>'Fornecedor teste','category'=>'supplies','due_on'=>'2026-10-01','amount'=>'100,01'];}
 private function expense():Expense{$this->post(route('expenses.store'),$this->form())->assertSessionHasNoErrors();return Expense::latest('id')->first();}
 private function payment(string $amount='40,00'):array{return ['request_id'=>(string)Str::uuid(),'amount'=>$amount,'paid_on'=>'2026-10-01','method'=>'pix','acknowledge'=>'1'];}
 public function test_create_idempotence_encryption_and_draft_edit_conflicts():void{$f=$this->form();$this->post(route('expenses.store'),$f)->assertSessionHasNoErrors();$this->post(route('expenses.store'),$f)->assertSessionHasNoErrors();$this->assertDatabaseCount('financial_expenses',1);$e=Expense::sole();$this->assertSame(10001,$e->amount_cents);$this->assertStringNotContainsString('Compra de materiais',DB::table('financial_expenses')->value('description'));$f['revision']=$e->revision;$f['amount']='120,01';$this->put(route('expenses.update',$e->id),$f)->assertSessionHasNoErrors();$this->put(route('expenses.update',$e->id),$f)->assertSessionHasErrors('revision');$this->assertSame(12001,$e->fresh()->amount_cents);$this->assertSame(10001,Event::oldest('id')->first()->payload['amount_cents']);$this->get(route('expenses.show',$e->id))->assertOk()->assertSee('Compra de materiais');$this->get(route('expenses.edit',$e->id))->assertOk();$this->get(route('expenses.create'))->assertOk();}
 public function test_partial_full_overpayment_retry_and_revision_guard():void{$e=$this->expense();$f=$this->payment();$this->post(route('expenses.pay',$e->id),$f)->assertSessionHasNoErrors();$this->post(route('expenses.pay',$e->id),$f)->assertSessionHasNoErrors();$this->assertDatabaseCount('expense_payments',1);$this->assertSame(6001,$e->fresh()->balanceCents());$this->post(route('expenses.pay',$e->id),$this->payment('60,02'))->assertSessionHasErrors('amount');$edit=$this->form()+['revision'=>$e->fresh()->revision];$this->put(route('expenses.update',$e->id),$edit)->assertSessionHasErrors('revision');$this->post(route('expenses.pay',$e->id),$this->payment('60,01'))->assertSessionHasNoErrors();$this->assertSame(0,$e->fresh()->balanceCents());$this->get(route('expenses.index',['status'=>'paid']))->assertOk()->assertSee('Compra de materiais');$this->get(route('expenses.index',['status'=>'open']))->assertOk()->assertDontSee('Compra de materiais');}
 public function test_reversal_owner_only_cancel_and_stale_payment():void{$e=$this->expense();$this->post(route('expenses.pay',$e->id),$this->payment());$p=Payment::sole();$this->post(route('expenses.cancel',$e->id),['revision'=>$e->fresh()->revision,'reason'=>'Despesa duplicada'])->assertSessionHasErrors('reason');$this->flushSession();$this->actingAs($this->user('reception'))->post(route('expenses.reverse',$p->id),['reason'=>'Lançamento incorreto'])->assertForbidden();$this->flushSession();$this->actingAs($this->owner)->post(route('expenses.reverse',$p->id),['reason'=>'Lançamento incorreto'])->assertSessionHasNoErrors();$this->post(route('expenses.reverse',$p->id),['reason'=>'Lançamento incorreto'])->assertSessionHasNoErrors();$this->assertSame(1,Event::where('event','reversed')->count());$this->assertSame(10001,$e->fresh()->balanceCents());$this->post(route('expenses.cancel',$e->id),['revision'=>$e->fresh()->revision,'reason'=>'Despesa duplicada'])->assertSessionHasNoErrors();$this->post(route('expenses.pay',$e->id),$this->payment())->assertStatus(422);}
 public function test_role_and_tenant_access_limits():void{$e=$this->expense();$this->post(route('expenses.pay',$e->id),$this->payment());$p=Payment::sole();$other=Company::create(['name'=>'Outra clínica','slug'=>'other-expenses']);$this->flushSession();$this->actingAs($this->user('owner',$other));$this->get(route('expenses.show',$e->id))->assertNotFound();$this->get(route('expenses.edit',$e->id))->assertNotFound();$this->post(route('expenses.pay',$e->id),$this->payment())->assertNotFound();$this->post(route('expenses.reverse',$p->id),['reason'=>'Tentativa inválida'])->assertNotFound();$this->get(route('expenses.index'))->assertOk()->assertDontSee('Compra de materiais');$this->get(route('finance.report'))->assertOk()->assertViewHas('spent',0);$this->flushSession();$this->actingAs($this->user('professional'));$this->get(route('expenses.index'))->assertForbidden();$this->get(route('finance.report'))->assertForbidden();$this->post(route('expenses.store'),$this->form())->assertForbidden();}
 public function test_invalid_values_future_payment_and_acknowledgement():void{$f=$this->form();$f['amount']='-1';$this->post(route('expenses.store'),$f)->assertSessionHasErrors('amount');$f['amount']='0';$this->post(route('expenses.store'),$f)->assertSessionHasErrors('amount');$f['amount']='10';$f['category']='unknown';$this->post(route('expenses.store'),$f)->assertSessionHasErrors('category');$e=$this->expense();$f=$this->payment();$f['paid_on']='2026-10-06';$this->post(route('expenses.pay',$e->id),$f)->assertSessionHasErrors('paid_on');$f=$this->payment();unset($f['acknowledge']);$this->post(route('expenses.pay',$e->id),$f)->assertSessionHasErrors('acknowledge');$this->get(route('finance.report',['from'=>'2026-10-01','to'=>'2026-01-01']))->assertSessionHasErrors('to');}
 public function test_due_period_summaries_and_paid_period_report_exclude_reversals():void{$e=$this->expense();$this->post(route('expenses.pay',$e->id),$this->payment());$this->get(route('expenses.index',['from'=>'2026-10-01','to'=>'2026-10-01']))->assertOk()->assertViewHas('stats',fn($s)=>(int)$s->pending===6001&&(int)$s->overdue===6001);
  $c=Customer::create(['company_id'=>$this->company->id,'name'=>'Paciente']);$q=FinancialQuote::create(['company_id'=>$this->company->id,'customer_id'=>$c->id,'created_by'=>$this->owner->id,'customer_name'=>$c->name,'description'=>'Tratamento','gross_cents'=>8000,'total_cents'=>8000,'status'=>'approved','request_key'=>hash('sha256','quote')]);$i=FinancialInstallment::create(['company_id'=>$this->company->id,'quote_id'=>$q->id,'sequence'=>1,'due_on'=>'2026-09-01','amount_cents'=>8000]);FinancialPayment::create(['company_id'=>$this->company->id,'installment_id'=>$i->id,'created_by'=>$this->owner->id,'amount_cents'=>8000,'paid_on'=>'2026-10-01','method'=>'pix','request_key'=>hash('sha256','payment')]);
  $this->get(route('finance.report',['from'=>'2026-10-01','to'=>'2026-10-01']))->assertOk()->assertViewHas('received',8000)->assertViewHas('spent',4000)->assertViewHas('categories',fn($c)=>(int)$c->first()->total===4000)->assertSee('R$ 40,00');$this->post(route('expenses.reverse',Payment::sole()->id),['reason'=>'Correção do lançamento']);$this->get(route('finance.report'))->assertOk()->assertViewHas('spent',0)->assertViewHas('received',8000);}
}
